"""Mock book dataset and data-access layer.

Each book is a dict with exactly the keys ``id`` (int), ``title`` (str),
``author`` (str) and ``year`` (int).
"""

BOOKS = [
    {"id": 1, "title": "The Hobbit", "author": "J.R.R. Tolkien", "year": 1937},
    {"id": 2, "title": "The Fellowship of the Ring", "author": "J.R.R. Tolkien", "year": 1954},
    {"id": 3, "title": "Pride and Prejudice", "author": "Jane Austen", "year": 1813},
    {"id": 4, "title": "Emma", "author": "Jane Austen", "year": 1815},
    {"id": 5, "title": "Nineteen Eighty-Four", "author": "George Orwell", "year": 1949},
    {"id": 6, "title": "Dune", "author": "Frank Herbert", "year": 1965},
]


class BookRepository:
    """Read-only access to a list of books. All results are shallow copies."""

    def __init__(self, books=None):
        source = BOOKS if books is None else books
        self._books = [dict(book) for book in source]

    def all(self):
        """Return copies of every book, in dataset order."""
        return [dict(book) for book in self._books]

    def get(self, book_id):
        """Return a copy of the book with ``book_id``, or None.

        Non-int ids (including bool) return None.
        """
        if not isinstance(book_id, int) or isinstance(book_id, bool):
            return None
        for book in self._books:
            if book["id"] == book_id:
                return dict(book)
        return None

    def search_by_author(self, name):
        """Return copies of books whose author contains ``name`` (case-insensitive)."""
        needle = name.casefold()
        return [dict(book) for book in self._books
                if needle in book["author"].casefold()]


DEFAULT_REPOSITORY = BookRepository()


def all():  # noqa: A001 - intentionally shadows the builtin within this module
    """Return all books from DEFAULT_REPOSITORY."""
    return DEFAULT_REPOSITORY.all()


def get(book_id):
    """Return one book from DEFAULT_REPOSITORY, or None."""
    return DEFAULT_REPOSITORY.get(book_id)


def search_by_author(name):
    """Search DEFAULT_REPOSITORY by author (case-insensitive substring)."""
    return DEFAULT_REPOSITORY.search_by_author(name)

"""Pure data-layer tests for books.data."""

import unittest

from books import data
from books.data import BOOKS, DEFAULT_REPOSITORY, BookRepository


def ids(books):
    return [book["id"] for book in books]


class DatasetTests(unittest.TestCase):
    def test_size(self):
        self.assertGreaterEqual(len(BOOKS), 5)
        self.assertLessEqual(len(BOOKS), 10)

    def test_schema(self):
        expected = {"id": int, "title": str, "author": str, "year": int}
        for book in BOOKS:
            with self.subTest(book=book):
                self.assertEqual(set(book), set(expected))
                for key, typ in expected.items():
                    self.assertIsInstance(book[key], typ)
                self.assertNotIsInstance(book["id"], bool)
                self.assertNotIsInstance(book["year"], bool)

    def test_unique_ids(self):
        self.assertEqual(len(set(ids(BOOKS))), len(BOOKS))


class RepositoryTests(unittest.TestCase):
    def setUp(self):
        self.repo = BookRepository()

    def test_all(self):
        self.assertEqual(self.repo.all(), BOOKS)

    def test_get_existing(self):
        book = self.repo.get(1)
        self.assertIsNotNone(book)
        self.assertEqual(book["title"], "The Hobbit")
        self.assertEqual(book, BOOKS[0])

    def test_get_missing(self):
        self.assertIsNone(self.repo.get(99999))

    def test_get_non_int(self):
        self.assertIsNone(self.repo.get("1"))
        self.assertIsNone(self.repo.get(True))
        self.assertIsNone(self.repo.get(1.0))
        self.assertIsNone(self.repo.get(None))

    def test_search_tolkien(self):
        for name in ("J.R.R. Tolkien", "TOLK", "tolk"):
            with self.subTest(name=name):
                self.assertEqual(ids(self.repo.search_by_author(name)), [1, 2])

    def test_search_austen(self):
        self.assertEqual(ids(self.repo.search_by_author("austen")), [3, 4])

    def test_search_no_match(self):
        self.assertEqual(self.repo.search_by_author("nobody"), [])

    def test_search_empty_matches_all(self):
        self.assertEqual(self.repo.search_by_author(""), BOOKS)

    def test_mutation_isolated(self):
        self.repo.get(1)["title"] = "Changed"
        self.repo.all()[0]["title"] = "Changed"
        self.repo.search_by_author("tolk")[0]["title"] = "Changed"
        self.assertEqual(self.repo.get(1)["title"], "The Hobbit")
        self.assertEqual(BOOKS[0]["title"], "The Hobbit")

    def test_constructor_copies_input(self):
        source = [{"id": 7, "title": "T", "author": "A", "year": 2000}]
        repo = BookRepository(source)
        source[0]["title"] = "Mutated"
        self.assertEqual(repo.get(7)["title"], "T")

    def test_custom_repository(self):
        custom = [{"id": 42, "title": "Custom", "author": "Some Writer", "year": 2020}]
        repo = BookRepository(custom)
        self.assertEqual(repo.all(), custom)
        self.assertEqual(repo.get(42), custom[0])
        self.assertIsNone(repo.get(1))
        self.assertEqual(repo.search_by_author("tolk"), [])
        self.assertEqual(ids(repo.search_by_author("writer")), [42])

    def test_empty_repository(self):
        repo = BookRepository([])
        self.assertEqual(repo.all(), [])
        self.assertIsNone(repo.get(1))


class ModuleFunctionTests(unittest.TestCase):
    def test_match_default_repository(self):
        self.assertEqual(data.all(), DEFAULT_REPOSITORY.all())
        self.assertEqual(data.all(), BOOKS)
        self.assertEqual(data.get(1), DEFAULT_REPOSITORY.get(1))
        self.assertIsNone(data.get(99999))
        self.assertEqual(data.search_by_author("tolk"),
                         DEFAULT_REPOSITORY.search_by_author("tolk"))
        self.assertEqual(ids(data.search_by_author("TOLK")), [1, 2])

    def test_module_mutation_isolated(self):
        data.get(2)["author"] = "X"
        self.assertEqual(data.get(2)["author"], "J.R.R. Tolkien")


if __name__ == "__main__":
    unittest.main()

"""Project-level checks: stdlib-only imports, no dependency files, README content."""

import ast
import pathlib
import unittest

REPO_ROOT = pathlib.Path(__file__).resolve().parent.parent

ALLOWED_MODULES = {
    "json", "http", "urllib", "argparse", "threading", "unittest",
    "contextlib", "io", "os", "sys", "re", "ast", "pathlib", "typing",
    "books", "tests",
}

SCANNED_DIRS = ("books", "tests")
FORBIDDEN_FILES = ("requirements.txt", "setup.py", "Pipfile", "pyproject.toml")
README_SNIPPETS = (
    "python -m unittest",
    "python3 -m books",
    "/books/<id>",
    "/books?author=",
    "not production-grade",
)


def _python_files():
    files = []
    for name in SCANNED_DIRS:
        files.extend(sorted((REPO_ROOT / name).rglob("*.py")))
    return files


def _top_level_imports(path):
    """Yield (lineno, top-level module) for every absolute import in ``path``."""
    tree = ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                yield node.lineno, alias.name.split(".")[0]
        elif isinstance(node, ast.ImportFrom):
            if node.level and node.level > 0:
                continue  # relative import: local by definition
            if node.module:
                yield node.lineno, node.module.split(".")[0]


class StdlibOnlyImportsTest(unittest.TestCase):
    def test_python_files_found(self):
        files = _python_files()
        names = {p.relative_to(REPO_ROOT).as_posix() for p in files}
        self.assertIn("books/server.py", names)
        self.assertIn("books/data.py", names)
        self.assertIn("tests/test_project.py", names)

    def test_all_imports_are_allowed(self):
        violations = []
        for path in _python_files():
            for lineno, module in _top_level_imports(path):
                if module not in ALLOWED_MODULES:
                    violations.append("{}:{}: {}".format(
                        path.relative_to(REPO_ROOT).as_posix(), lineno, module))
        self.assertEqual(violations, [], "non-allow-listed imports found")


class NoDependencyFilesTest(unittest.TestCase):
    def test_no_dependency_files_at_root(self):
        for name in FORBIDDEN_FILES:
            with self.subTest(file=name):
                self.assertFalse((REPO_ROOT / name).exists(),
                                 "{} must not exist".format(name))


class ReadmeTest(unittest.TestCase):
    def test_readme_exists_and_documents_project(self):
        readme = REPO_ROOT / "README.md"
        self.assertTrue(readme.is_file(), "README.md is missing")
        text = readme.read_text(encoding="utf-8")
        for snippet in README_SNIPPETS:
            with self.subTest(snippet=snippet):
                self.assertIn(snippet, text)


if __name__ == "__main__":
    unittest.main()

